const { createHash } = require('crypto');
const items = $input.all();

// 1. Verificação de concorrência / advisory lock
const firstItem = items[0]?.json;
if (firstItem && firstItem.acquired === false) {
  return [{
    json: {
      chat_id: 5281600644,
      text: '⚠️ <b>Reflexion Engine Semanal (WF-104)</b>\n\nExecução ignorada: outro processo de reflexão já está em andamento (lock 104104 ocupado).',
      lock_busy: true,
      no_candidates: true
    }
  }];
}

// 2. Filtrar desfechos válidos da semana (descartando nulos da outer join)
const outcomes = items
  .map(i => i.json)
  .filter(j => j && j.id && j.tenant_id);

const tenant_id = outcomes[0]?.tenant_id || 'default';
const total = outcomes.length;
const minSample = 5;
const nowIso = new Date().toISOString().slice(0, 10);

if (total < minSample) {
  const card = `🧠 <b>Balanço Semanal de Aprendizado 360 (WF-104)</b>\n` +
    `📅 <i>Semana: ${nowIso}</i> | Tenant: <code>${tenant_id}</code>\n\n` +
    `• <b>Amostra insuficiente na semana:</b> ${total} registros observados (Mínimo: ${minSample}).\n` +
    `• Nenhuma diretriz foi inferida para preservar a integridade das políticas.\n` +
    `• O motor continuará acumulando desfechos.`;
  return [{ json: { chat_id: 5281600644, text: card, insufficient: true, total, no_candidates: true } }];
}

let accepted = 0;
let edited = 0;
let rejected = 0;
const patterns = {};

for (const o of outcomes) {
  if (o.outcome_type === 'ACEITO_INTEGRAL') accepted++;
  else if (o.outcome_type === 'EDITADO_POR_RAFAEL') {
    edited++;
    const key = `${o.domain || 'GERAL'}:${o.delta_analysis?.edit_type || 'MODIFICADO'}`;
    patterns[key] = (patterns[key] || 0) + 1;
  }
  else if (o.outcome_type === 'RECUSADO_COM_MOTIVO') {
    rejected++;
    const key = `${o.domain || 'GERAL'}:REJEITADO`;
    patterns[key] = (patterns[key] || 0) + 1;
  }
}

const useful = accepted + edited;
const durPct = ((useful / total) * 100).toFixed(1);
const statusIcon = durPct >= 85.0 ? '🟢 <b>META BATIDA</b>' : '🟡 <b>ABAIXO DA META</b>';

function deterministicUuid(seed) {
  const hash = createHash('sha256').update(seed, 'utf8').digest('hex');
  return [
    hash.slice(0, 8),
    hash.slice(8, 12),
    '5' + hash.slice(13, 16),
    ((parseInt(hash.slice(16, 18), 16) & 0x3f) | 0x80).toString(16) + hash.slice(18, 20),
    hash.slice(20, 32)
  ].join('-');
}

const candidates = [];
for (const [key, count] of Object.entries(patterns)) {
  if (count >= 2) {
    const [dom, type] = key.split(':');
    let rule = `Ajustar propostas em ${dom} conforme preferências de Rafael.`;
    let risk = 'LOW';
    let category = 'COMMUNICATION_CADENCE';
    if (type === 'MADE_MORE_CONCISE') {
      rule = `Em ${dom}, gerar propostas mais concisas e diretas.`;
      category = 'STYLE_FORMATTING';
    } else if (type === 'EXPANDED_DETAILS') {
      rule = `Em ${dom}, detalhar os impactos operacionais antes do envio.`;
      category = 'STYLE_FORMATTING';
    } else if (type === 'REJEITADO') {
      rule = `Em ${dom}, reavaliar ofertas e argumentos previamente recusados.`;
      risk = 'HIGH';
      category = 'COMPLIANCE';
    }

    const seed = `${tenant_id}:${dom}:${type}:${rule}`;
    const candidateId = deterministicUuid(seed);
    const learning_run_id = `run-${candidateId.slice(0, 8)}`;
    const idempotency_key = `pk:${tenant_id}:${dom}:${deterministicUuid(dom + ':' + type).slice(0, 16)}`;
    const score = 0.650;

    // Lockdown de privilégio: WF-104 NUNCA autopromove diretamente nem assume aprovação de Rafael.
    // Todas as regras propostas entram estritamente como CANDIDATE / MANUAL_REVIEW.
    candidates.push({
      id: candidateId,
      tenant_id,
      category,
      scope: 'INDICATOR',
      target_ref: dom,
      learned_rule: rule,
      confidence_score: 0.88,
      status: 'CANDIDATE',
      promotion_mode: 'MANUAL_REVIEW',
      promotion_policy_version: 'v2.3.2-db-authoritative',
      promotion_score: score,
      risk_level: risk,
      frequency: count,
      learning_run_id,
      idempotency_key
    });
  }
}

let card = `🧠 <b>Balanço Semanal de Aprendizado 360 (WF-104)</b>\n` +
  `📅 <i>Semana: ${nowIso}</i> | Tenant: <code>${tenant_id}</code>\n` +
  `━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n` +
  `📊 <b>Métricas de Assertividade da IA:</b>\n` +
  `• <b>Total de Propostas:</b> ${total}\n` +
  `• <b>Úteis / Aceitas:</b> ${useful} (${durPct}% de utilidade)\n` +
  `• <b>Ajustadas por Você:</b> ${edited}\n` +
  `• <b>Recusadas:</b> ${rejected}\n` +
  `• <b>Status da Meta (DUR ≥ 85%):</b> ${statusIcon}\n\n`;

if (candidates.length > 0) {
  card += `🔍 <b>Diretrizes Candidatas Submetidas para Revisão Soberana:</b>\n`;
  for (const c of candidates) {
    card += `  • <code>/aprovardiretriz ${c.id}</code>\n    <i>${c.learned_rule}</i>\n`;
  }
  card += `\n`;
} else {
  card += `💡 Nenhuma divergência recorrente detectada nesta semana. Sistema estável.\n\n`;
}

card += `━━━━━━━━━━━━━━━━━━━━━━━━━━\n<i>Candidatas registradas no PostgreSQL via create_learning_candidate.</i>`;

if (candidates.length === 0) {
  return [{ json: { chat_id: 5281600644, text: card, no_candidates: true } }];
}

// Gestão de memória do n8n: purga objetos pesados e retorna apenas metadados necessários
return candidates.map(c => ({
  json: {
    id: c.id,
    tenant_id: c.tenant_id,
    category: c.category,
    scope: c.scope,
    target_ref: c.target_ref,
    learned_rule: c.learned_rule,
    confidence_score: c.confidence_score,
    risk_level: c.risk_level,
    frequency: c.frequency,
    learning_run_id: c.learning_run_id,
    idempotency_key: c.idempotency_key,
    text: card,
    chat_id: 5281600644
  }
}));
